// EGM96 geoid undulation lookup (1° grid generated by scripts/build-data.mjs).
// Elevation sources (GSI DEM, AWS Terrarium) give heights above mean sea level,
// while CesiumJS and 3D Tiles (PLATEAU etc.) use WGS84 ellipsoidal heights.
// Ellipsoidal height = orthometric height + geoid undulation (N).

const ROWS = 181;
const COLS = 361;
let grid: Int16Array | null = null;
let loading: Promise<void> | null = null;

export function loadGeoid(): Promise<void> {
  if (!loading) {
    loading = fetch('./data/geoid.bin')
      .then((r) => {
        if (!r.ok) throw new Error('geoid ' + r.status);
        return r.arrayBuffer();
      })
      .then((b) => {
        grid = new Int16Array(b);
      })
      .catch((e) => {
        console.warn('geoid grid unavailable, using N=0', e);
      });
  }
  return loading;
}

/** Geoid undulation N in metres for lat/lon in degrees (bilinear). */
export function geoidHeight(lat: number, lon: number): number {
  if (!grid) return 0;
  const r = Math.min(ROWS - 1.0001, Math.max(0, 90 - lat));
  let c = lon + 180;
  c = ((c % 360) + 360) % 360;
  const r0 = Math.floor(r);
  const c0 = Math.floor(c);
  const fr = r - r0;
  const fc = c - c0;
  const c1 = Math.min(COLS - 1, c0 + 1);
  const g = grid;
  const v00 = g[r0 * COLS + c0];
  const v01 = g[r0 * COLS + c1];
  const v10 = g[(r0 + 1) * COLS + c0];
  const v11 = g[(r0 + 1) * COLS + c1];
  return ((v00 * (1 - fc) + v01 * fc) * (1 - fr) + (v10 * (1 - fc) + v11 * fc) * fr) / 10;
}
